import { Group, Mesh, MeshPhysicalNodeMaterial, MeshBasicNodeMaterial, CylinderGeometry, SphereGeometry, CircleGeometry, PlaneGeometry, Vector3 } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, uniform, time, Fn, color, dot, length, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Material helpers
  const makeSteelMaterial = () => {
    const mat = new MeshPhysicalNodeMaterial();
    mat.roughness = 0.5;
    mat.metalness = 0.55;
    mat.clearcoat = 0.2;
    mat.clearcoatRoughness = 0.3;
    mat.anisotropy = 0.7;
    mat.anisotropyRotation = 0; // radial orientation will be set per vertex? Not simple; we rely on mesh UV.
    return mat;
  };

  // Load primary gear (async)
  const loadPromise = ctx.glbLoader.loadGLB(config.meshUrl);
  let primaryGear, secondaryGear;
  let gearMaterials = [];

  loadPromise.then((gltf) => {
    const scene = gltf.scene;
    // Assume single mesh, or traverse to find first
    scene.traverse((child) => {
      if (child.isMesh) {
        // Clone geometry and material for primary
        const geom = child.geometry.clone();
        const mat = makeSteelMaterial();
        mat.copy(child.material); // copy attributes if any
        // Override PBR values
        mat.roughness = 0.5;
        mat.metalness = 0.55;
        mat.clearcoat = 0.2;
        mat.clearcoatRoughness = 0.3;
        mat.anisotropy = 0.7;
        mat.anisotropyRotation = 0;
        mat.needsUpdate = true;

        primaryGear = new Mesh(geom, mat);
        primaryGear.scale.set(1.6, 1.6, 1.6);
        group.add(primaryGear);

        // Secondary gear: clone geometry and material
        const geom2 = child.geometry.clone();
        const mat2 = makeSteelMaterial();
        mat2.copy(child.material);
        mat2.roughness = 0.5;
        mat2.metalness = 0.55;
        mat2.clearcoat = 0.2;
        mat2.clearcoatRoughness = 0.3;
        mat2.anisotropy = 0.7;
        mat2.anisotropyRotation = 0;
        mat2.needsUpdate = true;

        secondaryGear = new Mesh(geom2, mat2);
        secondaryGear.scale.set(0.9, 0.9, 0.9);
        secondaryGear.position.set(1.15, 0.35, -0.1);
        group.add(secondaryGear);

        gearMaterials.push(mat, mat2);
      }
    });

    // Start rotational animations after meshes loaded
    const gearTimeline = gsap.timeline({ paused: true });
    // Primary rotates at 0.08 rad/s => full revolution in ~78.54s
    gearTimeline.to(primaryGear.rotation, {
      z: Math.PI * 2,
      duration: (2 * Math.PI) / 0.08,
      ease: 'none',
      repeat: -1
    }, 0);
    // Secondary rotates at -0.142 rad/s
    gearTimeline.to(secondaryGear.rotation, {
      z: -Math.PI * 2,
      duration: (2 * Math.PI) / 0.142,
      ease: 'none',
      repeat: -1
    }, 0);
    gearTimeline.resume();
    // Store for cleanup
    group.userData._gearTimeline = gearTimeline;
  });

  // Jewel pivot (placed regardless of load, will be on top after load)
  const jewelGeom = new SphereGeometry(0.12, 24, 24);
  const jewelMat = new MeshPhysicalNodeMaterial();
  jewelMat.color.set('#ff2a38');
  jewelMat.transmission = 0.6;
  jewelMat.ior = 1.76;
  jewelMat.emissive.set('#ff2a38');
  jewelMat.emissiveIntensity = 1.8;
  const jewel = new Mesh(jewelGeom, jewelMat);
  jewel.position.set(0, 0, 0);
  group.add(jewel);

  // Arbor shafts (cylinders along z)
  const arborGeom = new CylinderGeometry(0.05, 0.05, 0.8, 8);
  arborGeom.rotateX(Math.PI / 2); // align to z-axis
  const arborMat = new MeshPhysicalNodeMaterial();
  arborMat.color.set('#16161d');
  // Primary arbor
  const arbor1 = new Mesh(arborGeom, arborMat);
  arbor1.position.set(0, 0, 0);
  group.add(arbor1);
  // Secondary arbor
  const arbor2 = new Mesh(arborGeom, arborMat);
  arbor2.position.set(1.15, 0.35, -0.1);
  group.add(arbor2);

  // Contact shadow plane (radial gradient)
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.5,
    depthWrite: false
  });
  // TSL node: radial gradient based on UV centered
  const shadowUV = uv();
  const center = vec2(0.5, 0.5);
  const dist = length(shadowUV.sub(center));
  const alpha = smoothstep(0.0, 0.5, 1.0 - dist); // fade out from center
  shadowMat.opacityNode = alpha;
  shadowMat.side = 0; // DoubleSide? Not needed
  const shadowGeom = new PlaneGeometry(2.6, 1.2);
  const shadowMesh = new Mesh(shadowGeom, shadowMat);
  shadowMesh.position.set(0, -1.2, 0);
  shadowMesh.rotation.x = -Math.PI / 2; // face up? Actually we want it to lie flat on y plane? The spec says contact shadow ellipse, presumably on ground plane (y=-1.2). So it should be horizontal.
  // Actually we want it to be a decal on the ground, so we keep it perpendicular to y? But easier: place it as a plane facing upward? But plane's normal is +z by default. We'll rotate to face up: rotate.x = -Math.PI/2.
  group.add(shadowMesh);

  // Backdrop plane with gradient
  const backdropMat = new MeshBasicNodeMaterial({
    side: 2, // BackSide? Actually it's behind the scene, so we can use FrontSide and place at z=-3.
  });
  // Gradient from stops: #0b0b10 at 0, #101017 at 0.65, #16161d at 1
  const vCoord = uv().y; // y goes from 0 (bottom) to 1 (top)
  const color0 = color('#0b0b10');
  const color1 = color('#101017');
  const color2 = color('#16161d');
  // Manual mix: if v < 0.65 -> mix(color0, color1, v/0.65), else mix(color1, color2, (v-0.65)/(0.35))
  const t = vCoord.lessThan(0.65).select(
    mix(color0, color1, vCoord.div(0.65)),
    mix(color1, color2, vCoord.sub(0.65).div(0.35))
  );
  backdropMat.colorNode = t;
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -3);
  group.add(backdrop);

  // Linear fog hint: the scene already has fog? We'll add a fog uniform? Not necessary; we rely on scene's fog. Skip.

  // Text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize || 68,
      color: '#e8ecf2',
      align: 'center',
      maxWidthPx: 800
    });
    if (item.role === 'headline') {
      textObj.position.set(0, -1.7, 0);
    } else if (item.role === 'caption') {
      textObj.position.set(0, -2.1, 0);
    }
    // Scale text to scene units? createText returns in pixel units? Usually returns object with scale set appropriately. We leave as is, but we may need to scale down. For 68px it's likely large. We'll assume creator handles scene scaling.
    group.add(textObj);
  }

  // Apply cinematic primitive
  const orbitResult = ctx.primitives['orbit'](group, { speed: 0.08, radius: 0.2 });

  // Cleanup
  group.userData.cleanup = () => {
    // Kill gear timeline if exists
    if (group.userData._gearTimeline) {
      group.userData._gearTimeline.kill();
    }
    // Dispose materials
    gearMaterials.forEach(m => m.dispose());
    jewelMat.dispose();
    arborMat.dispose();
    shadowMat.dispose();
    backdropMat.dispose();
    // Dispose geometries
    jewelGeom.dispose();
    arborGeom.dispose();
    shadowGeom.dispose();
    backdropGeom.dispose();
    // Text objects: need to dispose their resources? Not provided, but we can call dispose on text objects if they have. We'll assume cleanup is handled.
    // Orbit primitive cleanup
    orbitResult.cleanup();
  };

  return group;
}
